      `PERSON_EDITED sheet=${sheet} by=uma name=Ada2 grade=B`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Ada2 grade=C`
    ]);
  });
  test("uniqueness across tree scenario 1", { tag: '@functionality' }, async ({ browser }) => {
